        [Test]
        public void StreamsReproduceRecordedValues()
        {
            foreach (var vector in Streams)
            {
                var stream = new StatelessRNG.Source(vector.Seed).CreateStream(new StatelessRNG.Domain(vector.Domain), vector.A, vector.B, vector.C);
                for (int draw = 0; draw < vector.Draws.Length; draw++)
                    Assert.That(stream.NextUInt64(), Is.EqualTo(vector.Draws[draw]), $"seed {vector.Seed} draw {draw}");
                Assert.That(stream.Range(-1000, 1000), Is.EqualTo(vector.Range));
                Assert.That(stream.Fork(vector.A).NextUInt64(), Is.EqualTo(vector.Fork));
            }
        }

        [Test]
        public void PartHashesReproduceRecordedValues()
        {
            Assert.That(StatelessRNG.Part("  Forest Loot "), Is.EqualTo(9000371558989458843UL));
            Assert.That(StatelessRNG.Part("forest loot"), Is.EqualTo(9000371558989458843UL));
            Assert.That(StatelessRNG.Part("Weather"), Is.EqualTo(146267062358059070UL));
            Assert.That(StatelessRNG.Part(""), Is.EqualTo(17241709254077376921UL));
        }

        [Test]
        public void FixedPointOperationsReproduceRecordedValues()
        {
            foreach (var row in FixedPoint)
            {
                var a = FP.FromRaw(row[0]);
                var b = FP.FromRaw(row[1]);
                Assert.That((a + b).RawValue, Is.EqualTo(row[2]));
                Assert.That((a - b).RawValue, Is.EqualTo(row[3]));
                Assert.That((a * b).RawValue, Is.EqualTo(row[4]));
                Assert.That((a / b).RawValue, Is.EqualTo(row[5]));
                Assert.That(FP.Sqrt(FP.Abs(a)).RawValue, Is.EqualTo(row[6]));
                Assert.That(FP.Sin(a).RawValue, Is.EqualTo(row[7]));
                Assert.That(FP.Atan2(a, b).RawValue, Is.EqualTo(row[8]));
            }
        }
